pos: int
sym: str
src: str

def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)

def expression() -> str:
  ws()
  p = term()
  while sym in ('+', '-'):
    op = sym
    nxt()
    ws()
    p += ' ' + term() + ' ' + op
  return p

def term() -> str:
  p = power()
  while sym in ('*', '/'):
    op = sym
    nxt()
    ws()
    p += ' ' + power() + ' ' + op
  return p

def power() -> str:
  p = unary()
  if sym == '^':
    nxt()
    ws()
    p += ' ' + power() + ' ^'
  return p

def unary() -> str:
  if sym == '-':
    nxt()
    ws()
    return unary() + ' ~'
  return factor()

def factor() -> str:
  if '0' <= sym <= '9':
    p = integer()
  elif sym == '(':
    nxt()
    p = expression()
    if sym == ')':
      nxt()
      ws()
    else:
      raise Exception("')' expected at " + str(pos))
  else:
    raise Exception('invalid character at ' + str(pos))
  return p

def integer() -> str:
  p = digit()
  while '0' <= sym <= '9':
    p += digit()
  ws()
  return p

def digit() -> str:
  p = sym
  nxt()
  return p

def ws():
  while sym == ' ':
    nxt()

def convert(s) -> str:
  global src, pos
  src, pos = s, 0
  nxt()
  p = expression()
